def test_path_like_extra_subtype():
    class Model(BaseModel):
        str_type: os.PathLike[str]
        byte_type: os.PathLike[bytes]
        any_type: os.PathLike[Any]

    m = Model(
        str_type='/foo/bar',
        byte_type=b'/foo/bar',
        any_type='/foo/bar',
    )
