        {
            'type': 'path_type',
            'loc': ('str_type',),
            'msg': "Input is not a valid path for <class 'os.PathLike'>",
            'input': b'/foo/bar',
        },
        {
            'type': 'path_type',
            'loc': ('byte_type',),
            'msg': "Input is not a valid path for <class 'os.PathLike'>",
            'input': '/foo/bar',
        },
        {
            'type': 'path_type',
