    def _determine_show_progress_info(
        self,
    ) -> Literal["progress", "count", "times", False]:
        """Return whether we should display progress information based on the current config."""
        # do not show progress if we are not capturing output (#3038) unless explicitly
        # overridden by progress-even-when-capture-no
        if (
            self.config.getoption("capture", "no") == "no"
            and self.config.getini("console_output_style")
            != "progress-even-when-capture-no"
        ):
            return False
        # do not show progress if we are showing fixture setup/teardown
        if self.config.getoption("setupshow", False):
            return False
        cfg: _ConsoleOutputStyle = self.config.getini("console_output_style")
        match cfg:
            case "progress" | "progress-even-when-capture-no":
                return "progress"
            case "count":
                return "count"
            case "times":
                return "times"
            case "classic":
                return False
            case unreachable:
                compat.assert_never(unreachable)

