def materialize_with_truncation(lines: Iterable[str], config: Config) -> list[str]:
    """Materialise a streaming explanation, applying truncation lazily.

    Pulls from ``lines`` only until the truncation threshold is reached;
    the rest of the iterator is dropped without being consumed.
    """
    should_truncate, budget = _get_truncation_parameters(config)
    if not should_truncate:
        return list(lines)

    tolerable_max_chars = budget.max_chars + TRUNCATION_FOOTER_CHARS
    # Pull one line past the point where ``_truncate_explanation`` keeps the
    # body whole (``max_lines + TRUNCATION_FOOTER_LINES``) so it can detect the
    # overflow, without us materialising more than we need.
    line_cap = (
        budget.max_lines + TRUNCATION_FOOTER_LINES + 1 if budget.max_lines > 0 else None
    )
    buffered: list[str] = []
    char_count = 0
    for line in lines:
        buffered.append(line)
        char_count += len(line)
        if line_cap is not None and len(buffered) >= line_cap:
            break
        if budget.max_chars > 0 and char_count > tolerable_max_chars:
            break
    else:
        # Iterator exhausted within limits — nothing to truncate.
        return buffered

    return _truncate_explanation(buffered, budget)

def _get_truncation_parameters(config: Config) -> tuple[bool, TruncationBudget]:
    """Return the truncation parameters from the given config, as (should truncate, budget)."""
    # We do not need to truncate if one of these conditions is met:
    # 1. Verbosity level is 2 or more;
    # 2. Test is being run in CI environment;
    # 3. Both truncation_limit_lines and truncation_limit_chars
    #    are set to 0 explicitly.
    verbose = config.get_verbosity(Config.VERBOSITY_ASSERTIONS)
    if verbose >= 2 or running_on_ci():
        return False, NO_TRUNCATION_BUDGET

    budget = _budget_from_config(config)
    should_truncate = budget.max_lines > 0 or budget.max_chars > 0
    return should_truncate, budget

def _budget_from_config(config: Config) -> TruncationBudget:
    """Build a budget from the ``truncation_limit_*`` ini options.

    ``getini`` returns ``None`` when an option is unset, which falls back to
    the default limit.
    """
    max_lines = config.getini("truncation_limit_lines")
    max_chars = config.getini("truncation_limit_chars")
    return TruncationBudget(
        max_lines=(
            TruncationBudget.DEFAULT_MAX_LINES if max_lines is None else int(max_lines)
        ),
        max_chars=(
            TruncationBudget.DEFAULT_MAX_CHARS if max_chars is None else int(max_chars)
        ),
    )

def _compare_eq_cls(
    left: object,
    right: object,
    highlighter: _HighlightFunc,
    verbose: int,
    assertion_text_diff_style: _AssertionTextDiffStyle,
) -> Iterator[str]:
    if not has_default_eq(left):
        return
    if isdatacls(left):
        all_fields = dataclasses.fields(left)
        fields_to_check = [info.name for info in all_fields if info.compare]
    elif isattrs(left):
        all_fields = left.__attrs_attrs__  # type: ignore[attr-defined]
        fields_to_check = [field.name for field in all_fields if getattr(field, "eq")]
    elif isnamedtuple(left):
        fields_to_check = left._fields  # type: ignore[attr-defined]
    else:
        assert False

    indent = "  "
    same = []
    diff = []
    for field in fields_to_check:
        if getattr(left, field) == getattr(right, field):
            same.append(field)
        else:
            diff.append(field)

    if same or diff:
        yield ""
    if same and verbose < 2:
        yield f"Omitting {len(same)} identical items, use -vv to show"
    elif same:
        yield "Matching attributes:"
        yield from highlighter(pprint.pformat(same)).splitlines()
    if diff:
        yield "Differing attributes:"
        yield from highlighter(pprint.pformat(diff)).splitlines()
        for field in diff:
            field_left = getattr(left, field)
            field_right = getattr(right, field)
            yield ""
            yield f"Drill down into differing attribute {field}:"
            yield f"{indent}{field}: {highlighter(repr(field_left))} != {highlighter(repr(field_right))}"
            for line in _compare_eq_any(
                field_left,
                field_right,
                highlighter,
                verbose,
                assertion_text_diff_style,
            ):
                yield indent + line

def _compare_eq_mapping(
    left: Mapping[object, object],
    right: Mapping[object, object],
    highlighter: _HighlightFunc,
    verbose: int = 0,
    truncation_budget: TruncationBudget = NO_TRUNCATION_BUDGET,
) -> Iterator[str]:
    set_left = set(left)
    set_right = set(right)
    common = set_left.intersection(set_right)
    same = {k: left[k] for k in common if left[k] == right[k]}
    if same and verbose < 2:
        yield f"Omitting {len(same)} identical items, use -vv to show"
    elif same:
        yield "Common items:"
        yield from highlighter(pprint.pformat(same)).splitlines()
    diff = {k for k in common if left[k] != right[k]}
    if diff:
        yield "Differing items:"
        for k in diff:
            yield (
                highlighter(saferepr({k: left[k]}))
                + " != "
                + highlighter(saferepr({k: right[k]}))
            )
    extra_left = set_left - set_right
    len_extra_left = len(extra_left)
    if len_extra_left:
        yield f"Left contains {len_extra_left} more item{'' if len_extra_left == 1 else 's'}:"
        yield from _format_extra_items(left, extra_left, highlighter, truncation_budget)
    extra_right = set_right - set_left
    len_extra_right = len(extra_right)
    if len_extra_right:
        yield f"Right contains {len_extra_right} more item{'' if len_extra_right == 1 else 's'}:"
        yield from _format_extra_items(
            right, extra_right, highlighter, truncation_budget
        )

def _format_extra_items(
    mapping: Mapping[object, object],
    keys: Collection[object],
    highlighter: _HighlightFunc,
    truncation_budget: TruncationBudget,
) -> Iterator[str]:
    """Render the "X contains N more items" subdict."""
    max_lines = truncation_budget.max_lines
    if max_lines == 0 or len(keys) <= max_lines:
        # If no need to truncate, let pprint handle it.
        yield from highlighter(
            pprint.pformat({k: mapping[k] for k in keys})
        ).splitlines()
    else:
        # To avoid spending effort on formatting entries that would be truncated,
        # only format the needed entries, keeping the sorting that pprint would use.
        for k in heapq.nsmallest(max_lines, keys, key=_safe_key):
            yield highlighter(saferepr({k: mapping[k]}))

def _set_one_sided_diff(
    posn: str,
    set1: AbstractSet[object],
    set2: AbstractSet[object],
    highlighter: _HighlightFunc,
) -> Iterator[str]:
    diff = set1 - set2
    if diff:
        yield f"Extra items in the {posn} set:"
        for item in diff:
            yield highlighter(saferepr(item))

def _compare_gt_set(
    left: AbstractSet[object],
    right: AbstractSet[object],
    highlighter: _HighlightFunc,
    verbose: int = 0,
) -> Iterator[str]:
    if left == right:
        yield "Both sets are equal"
    else:
        yield from _set_one_sided_diff("right", right, left, highlighter)

def _compare_lt_set(
    left: AbstractSet[object],
    right: AbstractSet[object],
    highlighter: _HighlightFunc,
    verbose: int = 0,
) -> Iterator[str]:
    if left == right:
        yield "Both sets are equal"
    else:
        yield from _set_one_sided_diff("left", left, right, highlighter)

def isiterable(obj: object) -> TypeGuard[collections.abc.Iterable[object]]:
    try:
