        self,
        object: Any,
        indent: int,
        allowance: int,
        context: set[int],
        level: int,
    ) -> Iterator[str]:
        if not len(object):
            yield repr(object)
            return
        chunks = []
        lines = object.splitlines(True)
        if level == 1:
            indent += 1
            allowance += 1
