def callop(
    op: str,
    left: Any,
    right: Any,
    verbose: int = 0,
    assertion_text_diff_style: _AssertionTextDiffStyle = "ndiff",
) -> list[str] | None:
    config = mock_config(
        verbose=verbose,
        assertion_text_diff_style=assertion_text_diff_style,
    )
    return plugin.pytest_assertrepr_compare(config, op, left, right)

def callequal(
    left: Any,
    right: Any,
    verbose: int = 0,
    assertion_text_diff_style: _AssertionTextDiffStyle = "ndiff",
) -> list[str] | None:
    return callop(
        "==",
        left,
        right,
        verbose,
        assertion_text_diff_style=assertion_text_diff_style,
    )

