    def test_compare_left_operand_precedes_walrus(self) -> None:
        assert_evaluation_order("""
            def check():
                def identity(v):
                    return v
                value = "Hello"
                try:
                    assert value != identity(value := value.lower())
                except AssertionError:
                    return "raised", value
                return "passed", value
            """)

