        assert request.fixturenames == [
            "my_tmp_path_factory",
            "s1",
            "p1",
            "m1",
            "f1",
            "my_tmp_path",
            "f2",
        ]
        result = pytester.runpytest("-vv")
        result.assert_outcomes(passed=1)

