def _make_cached_stream_func(
    src_func: Callable[[], TextIO],
    wrapper_func: Callable[[], TextIO],
) -> Callable[[], TextIO]:
    cache: MutableMapping[TextIO, TextIO] = WeakKeyDictionary()

    def func() -> TextIO:
        stream = src_func()

        try:
            rv = cache.get(stream)
        except Exception:  # pragma: no cover
            rv = None
        if rv is not None:
            return rv
        rv = wrapper_func()
        try:
            cache[stream] = rv
        except Exception:  # pragma: no cover
            pass
        return rv

